import{_ as i,c as e,o as s,ag as l}from"./chunks/framework.DfL_BkQ-.js";const g=JSON.parse('{"title":"画面収録の権限ガイド（macOS）","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/screen-recording.md","filePath":"ja/guide/screen-recording.md","lastUpdated":1794112334000}'),t={name:"ja/guide/screen-recording.md"};function r(o,a,n,c,p,h){return s(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="画面収録の権限ガイド-macos" tabindex="-1">画面収録の権限ガイド（macOS） <a class="header-anchor" href="#画面収録の権限ガイド-macos" aria-label="Permalink to &quot;画面収録の権限ガイド（macOS）&quot;">​</a></h1><h2 id="nicasa-に画面収録の権限が必要な理由" tabindex="-1">Nicasa に画面収録の権限が必要な理由 <a class="header-anchor" href="#nicasa-に画面収録の権限が必要な理由" aria-label="Permalink to &quot;Nicasa に画面収録の権限が必要な理由&quot;">​</a></h2><p>macOS では、スクリーンショットや画面キャプチャを行うアプリは、ディスプレイからピクセルを読み取るために画面収録の権限を取得する必要があります。</p><p>macOS 10.15 Catalina 以降、Apple はより厳格なプライバシー保護を導入しました。画面の内容をキャプチャするアプリ（スクリーンショットを含む）は、すべてユーザーの明示的な承認が必要です。</p><p>これは Mac App Store からダウンロードしたアプリを含む、すべてのアプリに適用されます。</p><p><strong>この権限がないと、Nicasa はスクリーンショットの撮影や画面の録画ができません。</strong></p><h2 id="画面収録の権限を有効にする方法" tabindex="-1">画面収録の権限を有効にする方法 <a class="header-anchor" href="#画面収録の権限を有効にする方法" aria-label="Permalink to &quot;画面収録の権限を有効にする方法&quot;">​</a></h2><p>次の手順に従ってください：</p><ol><li><strong>システム設定</strong> を開きます</li><li><strong>プライバシーとセキュリティ</strong> に移動します</li><li><strong>画面収録</strong> を選択します</li><li>一覧から <strong>Nicasa</strong> を見つけてチェックを入れます</li></ol><p>アプリがすでに起動していた場合は、権限を有効にした後に Nicasa を再起動してください。</p><h2 id="権限のダイアログが表示されなかった場合" tabindex="-1">権限のダイアログが表示されなかった場合 <a class="header-anchor" href="#権限のダイアログが表示されなかった場合" aria-label="Permalink to &quot;権限のダイアログが表示されなかった場合&quot;">​</a></h2><p>権限のダイアログは通常、アプリが初めて画面をキャプチャしようとしたときに表示されます。</p><p>ダイアログが表示されなかった場合、次のいずれかが原因と考えられます：</p><ul><li>権限の要求が以前に拒否された</li><li>macOS が権限の状態をキャッシュしている</li><li>ダイアログが表示される前にアプリがキャプチャを実行した</li></ul><p>この場合は、権限をリセットする必要があります。</p><h2 id="画面収録の権限をリセットする" tabindex="-1">画面収録の権限をリセットする <a class="header-anchor" href="#画面収録の権限をリセットする" aria-label="Permalink to &quot;画面収録の権限をリセットする&quot;">​</a></h2><p>ターミナルで次のコマンドを実行すると権限をリセットできます：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tccutil</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ScreenCapture</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.nicasa.nue</span></span></code></pre></div><p>コマンドを実行した後：</p><ol><li>Nicasa を再起動します</li><li>スクリーンショット機能を再度実行します</li><li>macOS が権限のダイアログを再表示します</li></ol><h2 id="リセットしても解決しない場合" tabindex="-1">リセットしても解決しない場合 <a class="header-anchor" href="#リセットしても解決しない場合" aria-label="Permalink to &quot;リセットしても解決しない場合&quot;">​</a></h2><p>まれに、macOS が無効な権限の状態を保持していることがあります。</p><p>権限のリセットで問題が解決しない場合は、次の手順をお試しください：</p><ol><li>Nicasa を終了します</li><li>アプリケーションフォルダから Nicasa を削除します</li><li>Mac App Store から最新版を再インストールします</li><li>アプリを再度起動します</li><li>macOS が画面収録の権限を求めたら <strong>許可</strong> を選択します</li></ol><p>アプリを再インストールすると、macOS に権限のエントリを再作成させることができます。</p><h2 id="別の手動修正方法" tabindex="-1">別の手動修正方法 <a class="header-anchor" href="#別の手動修正方法" aria-label="Permalink to &quot;別の手動修正方法&quot;">​</a></h2><p>権限を手動で切り替えることもできます：</p><ol><li><strong>システム設定</strong> を開きます</li><li><strong>プライバシーとセキュリティ</strong> に移動します</li><li><strong>画面収録</strong> を開きます</li><li>Nicasa のチェックを外し、もう一度チェックを入れます</li><li>Nicasa を再起動します</li></ol><h2 id="セキュリティに関する注意" tabindex="-1">セキュリティに関する注意 <a class="header-anchor" href="#セキュリティに関する注意" aria-label="Permalink to &quot;セキュリティに関する注意&quot;">​</a></h2><p>画面収録の権限を付与しても、Nicasa がシステムを操作できるようになるわけではありません。</p><p>スクリーンショットとキャプチャ機能のために、画面のピクセルを読み取ることだけが許可されます。</p><p>この権限は次の場所でいつでも取り消せます： <strong>システム設定 → プライバシーとセキュリティ → 画面収録</strong></p>',32)])])}const u=i(t,[["render",r]]);export{g as __pageData,u as default};
